package com.guocheng.mediapocket;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;
/** Embedded community catalog. Installation links return to the existing confirmation/import dialog. */
public final class AddonMarketActivity extends Activity {
 static final String HOME="https://stremio-addons.net/";WebView web;TextView status;LinearLayout root;boolean light,failed;
 @Override public void onCreate(Bundle b){light=CinemaTheme.light(this);getTheme().applyStyle(light?android.R.style.Theme_Material_Light_NoActionBar:android.R.style.Theme_Material_NoActionBar,true);super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),0,dp(12),0);root.setBackgroundColor(light?0xffedf5f5:0xff10343e);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(button("‹ 返回",()->onBackPressed()));TextView title=new TextView(this);title.setText("插件市场");title.setTextSize(19);title.setTextColor(light?0xff173740:0xfff5fafb);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("首页",()->web.loadUrl(HOME)));bar.addView(button("刷新",()->web.reload()));root.addView(bar);status=new TextView(this);status.setTextSize(12);status.setTextColor(light?0xff52757c:0xffafcbd2);status.setPadding(dp(4),dp(6),dp(4),dp(6));status.setText("社区市场 · 点击安装后确认添加；列入市场不代表片源已实播验证");root.addView(status);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSupportMultipleWindows(false);settings.setUseWideViewPort(true);settings.setLoadWithOverviewMode(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
  web.setWebViewClient(new WebViewClient(){@Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap favicon){failed=false;}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return navigate(request.getUrl().toString());}@Override public boolean shouldOverrideUrlLoading(WebView view,String url){return navigate(url);}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame()){failed=true;status.setText("市场暂时无法连接 · 可刷新重试，或返回插件页手动添加地址");}}@Override public void onReceivedSslError(WebView view,android.webkit.SslErrorHandler handler,android.net.http.SslError error){handler.cancel();failed=true;status.setText("当前页面 TLS 连接失败 · 可返回插件页手动添加地址");}});
  web.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView view,int progress){if(failed)return;if(progress<100)status.setText("正在读取插件市场 · "+progress+"%");else status.setText("社区市场 · 选择插件后点安装，回到随影确认添加");}});if(b==null||web.restoreState(b)==null)web.loadUrl(HOME);
 }
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}Button button(String s,Runnable task){CinemaButton b=new CinemaButton(this,light);b.setText(s);b.setOnClickListener(v->task.run());return b;}
 boolean navigate(String raw){String url=raw;if(raw.startsWith("intent:"))try{Intent parsed=Intent.parseUri(raw,Intent.URI_INTENT_SCHEME);if(parsed.getData()!=null)url=parsed.getData().toString();else url=parsed.getStringExtra("browser_fallback_url");}catch(Exception e){return true;}
  String install=MarketInstallRules.manifest(url);if(install!=null){Intent in=new Intent(Intent.ACTION_VIEW,Uri.parse(install));in.setClassName(getPackageName(),"com.guocheng.mediapocket.MainActivity");in.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(in);finish();return true;}
  try{String scheme=Uri.parse(url).getScheme();if("https".equalsIgnoreCase(scheme)||"http".equalsIgnoreCase(scheme))return false;}catch(Exception ignored){}status.setText("此链接不能直接安装 · 请使用插件提供的 manifest 地址");return true;
 }
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override public void onSaveInstanceState(Bundle b){web.saveState(b);super.onSaveInstanceState(b);}
 @Override public void onDestroy(){if(web!=null){root.removeView(web);web.stopLoading();web.destroy();}super.onDestroy();}
}
